export function isInsideNepal(lat, lng) {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false;
  if (lat < NEPAL_BBOX.minLat || lat > NEPAL_BBOX.maxLat) return false;
  if (lng < NEPAL_BBOX.minLng || lng > NEPAL_BBOX.maxLng) return false;
  // Ray casting against the polygon ring.
  let inside = false;
  for (let i = 0, j = NEPAL_RING.length - 1; i < NEPAL_RING.length; j = i++) {
    const xi = NEPAL_RING[i][0], yi = NEPAL_RING[i][1];
    const xj = NEPAL_RING[j][0], yj = NEPAL_RING[j][1];
    const intersect = (yi > lat) !== (yj > lat) &&
      lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}
